'use client';

/**
 * @file useToastGesture.ts
 * @input Uses a resolved Toast edge direction, timer pause/resume hooks,
 *   dismissal callback, enabled state, and interactive-descendant policy
 * @output Returns the Toast card root ref and touch/pen gesture bindings
 * @position Internal Toast gesture unit; attached to the Toast card root
 */
import { useCallback, useEffect, useRef } from 'react';
const DRAG_PROMOTION_SLOP = 8;
const SWIPE_DISMISS_RATIO = 0.4;
const FLICK_MIN_DISTANCE = 48;
const FLICK_VELOCITY = 1.2;
const VERTICAL_INTENT_RATIO = 1.2;
const SWIPE_EXIT_DISTANCE = '120%';
const SWIPE_ACTIVE_FADE_MAX = 0.4;
const SWIPE_ACTIVE_SCALE_MAX = 0.02;
function swipeProgressValue(travel, surfaceSize) {
  return Math.min(Math.max(travel / surfaceSize, 0), 1);
}
function clearTransientStyles(root) {
  root.style.removeProperty('transition-duration');
  root.style.removeProperty('--_toast-swipe-y');
  root.style.removeProperty('--_toast-swipe-exit-y');
  root.style.removeProperty('--_toast-swipe-opacity');
  root.style.removeProperty('--_toast-swipe-scale');
}
export function useToastGesture({
  direction,
  enabled,
  canPauseTimer,
  isTimerPaused,
  pauseTimer,
  resumeTimer,
  dismiss,
  shouldIgnoreTarget
}) {
  const rootRef = useRef(null);
  const gestureRef = useRef(null);
  const resetGesture = useCallback(shouldResume => {
    const root = rootRef.current;
    const state = gestureRef.current;
    gestureRef.current = null;
    if (root) {
      clearTransientStyles(root);
    }
    if (shouldResume && state?.pausedTimer) {
      resumeTimer();
    }
  }, [resumeTimer]);
  const beginGesture = useCallback((point, target) => {
    const root = rootRef.current;
    if (!root || !enabled || gestureRef.current != null || shouldIgnoreTarget(target, root)) {
      return false;
    }
    const pausedTimer = canPauseTimer && !isTimerPaused();
    if (pausedTimer) {
      pauseTimer();
    }
    const surfaceSize = Math.max(root.getBoundingClientRect().height, 1);
    gestureRef.current = {
      pointerId: point.pointerId,
      startX: point.clientX,
      startY: point.clientY,
      startTime: Date.now(),
      direction,
      intent: 'pending',
      pausedTimer,
      surfaceSize,
      dismissThreshold: Math.max(surfaceSize * SWIPE_DISMISS_RATIO, FLICK_MIN_DISTANCE)
    };
    return true;
  }, [canPauseTimer, direction, enabled, isTimerPaused, pauseTimer, shouldIgnoreTarget]);
  const moveGesture = useCallback((point, preventDefault, releaseCapture) => {
    const state = gestureRef.current;
    const root = rootRef.current;
    if (!state || !root || point.pointerId !== state.pointerId) {
      return;
    }
    const deltaX = point.clientX - state.startX;
    const deltaY = point.clientY - state.startY;
    const absX = Math.abs(deltaX);
    const absY = Math.abs(deltaY);
    if (state.intent === 'pending') {
      if (absX > DRAG_PROMOTION_SLOP && absX > absY) {
        releaseCapture?.();
        resetGesture(true);
        return;
      }
      if (absY <= DRAG_PROMOTION_SLOP || absY <= absX * VERTICAL_INTENT_RATIO) {
        return;
      }
      state.intent = deltaY * state.direction > 0 ? 'vertical' : 'opposite';
      if (state.intent === 'opposite') {
        releaseCapture?.();
        resetGesture(true);
        return;
      }
      root.style.setProperty('transition-duration', '0s');
    }
    preventDefault();
    const travel = Math.max(0, deltaY * state.direction);
    const progress = swipeProgressValue(travel, state.surfaceSize);
    root.style.setProperty('--_toast-swipe-y', `${travel * state.direction}px`);
    root.style.setProperty('--_toast-swipe-opacity', (1 - progress * SWIPE_ACTIVE_FADE_MAX).toFixed(3));
    root.style.setProperty('--_toast-swipe-scale', (1 - progress * SWIPE_ACTIVE_SCALE_MAX).toFixed(3));
  }, [resetGesture]);
  const endGesture = useCallback(point => {
    const state = gestureRef.current;
    const root = rootRef.current;
    if (!state || !root || point.pointerId !== state.pointerId) {
      return;
    }
    const travel = Math.max(0, (point.clientY - state.startY) * state.direction);
    const elapsed = Math.max(1, Date.now() - state.startTime);
    const isDismissed = state.intent === 'vertical' && (travel >= state.dismissThreshold || travel >= FLICK_MIN_DISTANCE && travel / elapsed > FLICK_VELOCITY);
    gestureRef.current = null;
    root.style.removeProperty('transition-duration');
    if (isDismissed) {
      root.style.setProperty('--_toast-swipe-exit-y', state.direction === 1 ? SWIPE_EXIT_DISTANCE : `calc(-1 * ${SWIPE_EXIT_DISTANCE})`);
      dismiss();
      return;
    }
    clearTransientStyles(root);
    if (state.pausedTimer) {
      resumeTimer();
    }
  }, [dismiss, resumeTimer]);
  const handlePointerDown = useCallback(event => {
    if (event.pointerType === 'pen' && (event.button == null || event.button === 0) && beginGesture(event, event.target)) {
      rootRef.current?.setPointerCapture?.(event.pointerId);
    }
  }, [beginGesture]);
  const handlePointerMove = useCallback(event => {
    if (event.pointerType !== 'pen') {
      return;
    }
    moveGesture(event, () => event.preventDefault(), () => rootRef.current?.releasePointerCapture?.(event.pointerId));
  }, [moveGesture]);
  const handlePointerUp = useCallback(event => {
    if (event.pointerType !== 'pen') {
      return;
    }
    rootRef.current?.releasePointerCapture?.(event.pointerId);
    endGesture(event);
  }, [endGesture]);
  const handlePointerCancel = useCallback(event => {
    if (event.pointerType === 'pen' && gestureRef.current?.pointerId === event.pointerId) {
      resetGesture(true);
    }
  }, [resetGesture]);
  useEffect(() => {
    const root = rootRef.current;
    if (!root || !enabled) {
      return;
    }
    const point = touch => ({
      pointerId: touch.identifier,
      clientX: touch.clientX,
      clientY: touch.clientY
    });
    const changedTouch = event => {
      const pointerId = gestureRef.current?.pointerId;
      return pointerId == null ? undefined : [...event.changedTouches].find(touch => touch.identifier === pointerId);
    };
    const handleTouchStart = event => {
      const touch = event.touches.length === 1 ? event.changedTouches[0] : null;
      if (touch) {
        beginGesture(point(touch), event.target);
      }
    };
    const handleTouchMove = event => {
      const touch = changedTouch(event);
      if (touch) {
        moveGesture(point(touch), () => {
          if (event.cancelable) {
            event.preventDefault();
          }
        });
      }
    };
    const handleTouchEnd = event => {
      const touch = changedTouch(event);
      if (touch) {
        endGesture(point(touch));
      } else if (event.touches.length === 0) {
        resetGesture(true);
      }
    };
    const handleTouchCancel = () => resetGesture(true);
    root.addEventListener('touchstart', handleTouchStart, {
      passive: true
    });
    root.addEventListener('touchmove', handleTouchMove, {
      passive: false
    });
    root.addEventListener('touchend', handleTouchEnd, {
      passive: true
    });
    root.addEventListener('touchcancel', handleTouchCancel, {
      passive: true
    });
    return () => {
      root.removeEventListener('touchstart', handleTouchStart);
      root.removeEventListener('touchmove', handleTouchMove);
      root.removeEventListener('touchend', handleTouchEnd);
      root.removeEventListener('touchcancel', handleTouchCancel);
    };
  }, [beginGesture, enabled, endGesture, moveGesture, resetGesture]);
  return {
    rootRef,
    bindings: {
      onPointerDown: handlePointerDown,
      onPointerMove: handlePointerMove,
      onPointerUp: handlePointerUp,
      onPointerCancel: handlePointerCancel,
      onLostPointerCapture: handlePointerCancel
    }
  };
}